```java
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.List;
import java.util.ArrayList;

public class SecureCommandDemo {
    public static void pingHost(String host) throws Exception {
        // To fix this, we use the ProcessBuilder API with a List of arguments.
        // This treats the 'host' as a single literal argument rather than part of 
        // a shell command string, preventing command injection.
        List<String> command = new ArrayList<>();
        command.add("ping");
        command.add("-c");
        command.add("3");
        command.add(host); // The input is treated strictly as a parameter

        ProcessBuilder pb = new ProcessBuilder(command);
        Process process = pb.start();

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
        }
    }

    public static void main(String[] args) throws Exception {
        // The malicious input will now fail the ping command execution 
        // rather than executing the second command.
        pingHost("8.8.8.8; cat /etc/passwd");
    }
}
```

